package com.kamyabpakhsh.staff;

import android.app.*;import android.os.*;import android.graphics.Color;import android.graphics.Typeface;import android.text.InputType;import android.view.*;import android.widget.*;import android.graphics.drawable.GradientDrawable;

public class MainActivity extends Activity {
 int green=Color.rgb(0,168,107), dark=Color.rgb(7,26,20); LinearLayout root;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(dark);showLogin();}
 TextView text(String s,int sp){TextView v=new TextView(this);v.setText(s);v.setTextSize(sp);v.setTextColor(Color.WHITE);v.setGravity(Gravity.CENTER);v.setPadding(12,12,12,12);return v;}
 GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}
 void base(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setGravity(Gravity.CENTER_HORIZONTAL);root.setPadding(28,28,28,28);root.setBackgroundColor(dark);root.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);setContentView(root);}
 void showLogin(){base();Space top=new Space(this);root.addView(top,new LinearLayout.LayoutParams(1,35));ImageView logo=new ImageView(this);logo.setImageResource(com.kamyabpakhsh.staff.R.drawable.logo);logo.setScaleType(ImageView.ScaleType.CENTER_INSIDE);root.addView(logo,new LinearLayout.LayoutParams(-1,260));TextView title=text("سامانه داخلی پرسنل کامیاب پخش",22);title.setTypeface(null,Typeface.BOLD);root.addView(title);root.addView(text("ورود به حساب کاربری",16));EditText u=input("نام کاربری",false),p=input("رمز عبور",true);root.addView(u);root.addView(p);Button login=new Button(this);login.setText("ورود");login.setTextSize(18);login.setTextColor(Color.WHITE);login.setBackground(bg(green,24));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,130);lp.setMargins(0,25,0,0);root.addView(login,lp);login.setOnClickListener(v->showDashboard());root.addView(text("نسخه ۱.۰ • حسمان تجارت کامیاب",12));}
 EditText input(String hint,boolean pass){EditText e=new EditText(this);e.setHint(hint);e.setTextColor(Color.DKGRAY);e.setHintTextColor(Color.GRAY);e.setTextDirection(View.TEXT_DIRECTION_RTL);e.setPadding(25,0,25,0);e.setBackground(bg(Color.WHITE,22));if(pass)e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,120);lp.setMargins(0,16,0,0);e.setLayoutParams(lp);return e;}
 void showDashboard(){base();TextView h=text("کامیاب پخش  |  داشبورد پرسنل",22);h.setTypeface(null,Typeface.BOLD);root.addView(h);root.addView(text("سلام، همکار عزیز\nامروز آماده یک روز کاری موفق هستیم",16));String[] items={"👥 مدیریت پرسنل","📝 گزارش روزانه","🛒 ثبت سفارش","💰 پیگیری مطالبات","📦 مدیریت انبار","🚚 تحویل و توزیع","📊 گزارش‌های مدیریتی","⏰ حضور و غیاب","🔔 پیام‌ها و اعلان‌ها"};GridLayout grid=new GridLayout(this);grid.setColumnCount(2);grid.setAlignmentMode(GridLayout.ALIGN_BOUNDS);for(String s:items){TextView c=text(s,16);c.setTextColor(dark);c.setGravity(Gravity.CENTER);c.setBackground(bg(Color.WHITE,24));GridLayout.LayoutParams gp=new GridLayout.LayoutParams();gp.width=0;gp.height=145;gp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);gp.setMargins(8,8,8,8);grid.addView(c,gp);}ScrollView sc=new ScrollView(this);sc.addView(grid);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button out=new Button(this);out.setText("خروج از حساب");out.setOnClickListener(v->showLogin());root.addView(out,new LinearLayout.LayoutParams(-1,110));}
}
